import LensManager, { ILens, LensLayerName } from "#core/ui/lenses/lens-manager.js";

class DiscoveryLens implements ILens {
	activeLayers = new Set<LensLayerName>([
		"fxs-discovery-layer",
		"fxs-culture-borders-layer",
		"fxs-operation-target-layer",
	]);
	allowedLayers = new Set<LensLayerName>([
		"fxs-hexgrid-layer",
		"fxs-resource-layer",
		"fxs-yields-layer",
		"fxs-conquest-layer",
	]);
	skipCachingEnabledLayers = true;
}

declare global {
	interface LensTypeMap {
		"fxs-discovery-lens": DiscoveryLens;
	}
}

LensManager.registerLens("fxs-discovery-lens", new DiscoveryLens());
